class FurnitureCheck:
    """The left arm's moving links against the bench and the hotplate, for a stance (base x, y, heading, pedestal command) and joint vectors in the base's frame; the other arm is not part of it."""

    def __init__(self, ctx, open_bench=False, clearance=0.0):
        self.clearance = float(clearance)                # a hand or arm geom closer than this to the bench or the hotplate counts as a hit (0: touching or penetrating)
        self.model = m = copy.copy(ctx.m)
        m.body_pos[m.body("task_hotplate").id] = [ctx.hotplate_xy[0], ctx.hotplate_xy[1], ctx.top]
        bname = lambda g: m.body(int(m.geom_bodyid[g])).name
        col = np.array([bool(m.geom_contype[g] or m.geom_conaffinity[g]) for g in range(m.ngeom)])
        names = [bname(g) for g in range(m.ngeom)]
        self.hand = np.array([col[g] and names[g] in ("openarm_left_hand", "openarm_left_right_finger", "openarm_left_left_finger") for g in range(m.ngeom)])
        self.arm = np.array([col[g] and names[g].startswith("openarm_left_") and not names[g].endswith("link0") for g in range(m.ngeom)]) & ~self.hand
        self.furn = np.array([col[g] and names[g] in ("bench", "task_hotplate") and not (open_bench and m.geom(g).name.startswith("bench_frame")) for g in range(m.ngeom)])
        for g in range(m.ngeom):
            if not (self.hand[g] or self.arm[g] or self.furn[g]):
                m.geom_contype[g] = 0
                m.geom_conaffinity[g] = 0
        m.geom_margin[:] = max(self.clearance, 0.03)      # contacts are generated within the margin, so that the distance of near misses (up to 3 cm) is known
        self.data = d = mujoco.MjData(m)
        for sd in ("left", "right"):
            for j in arm_ids(m, sd)["finger_jnt"]:
                d.qpos[m.jnt_qposadr[j]] = STAGING_CFG["finger_open"]
        self.qadr = arm_ids(m, "left")["qadr"]
        self.pedestal = [m.joint(jn).qposadr[0] for jn in robot_specs.PEDESTAL_SPECS["joints"]]
        self.base_z = ctx.rg["base_z"]
        self.tcp = m.body("openarm_left_hand_tcp").id

    def place(self, stance):
        d = self.data
        x, y, th, q = stance
        d.qpos[0:7] = [x, y, self.base_z, math.cos(th / 2), 0.0, 0.0, math.sin(th / 2)]
        for a in self.pedestal:
            d.qpos[a] = q

    def check(self, stance, Q):
        """Q (c, 7) -> (hand_hit (c,), arm_hit (c,)) bool (a hit: closer than self.clearance, or touching), and the closest hand contact of each: self.depth (m, positive: penetration or
        distance shortfall below the clearance), self.pair ("hand geom vs furniture geom") and self.mindist (m, the hand's smallest distance to the bench or the hotplate, negative:
        penetration; 0.03 when nothing is within 3 cm)."""
        m, d = self.model, self.data
        self.place(stance)
        hh, ah = np.zeros(len(Q), bool), np.zeros(len(Q), bool)
        self.depth = np.zeros(len(Q))
        self.mindist = np.full(len(Q), 0.03)
        self.pair = [""] * len(Q)
        for i, q in enumerate(Q):
            d.qpos[self.qadr] = q
            mujoco.mj_kinematics(m, d)
            mujoco.mj_collision(m, d)
            for c in range(d.ncon):
                g1, g2 = d.contact.geom1[c], d.contact.geom2[c]
                dist = d.contact.dist[c]
                for a, b in ((g1, g2), (g2, g1)):
                    if self.furn[b]:
                        if self.hand[a]:
                            self.mindist[i] = min(self.mindist[i], dist)
                        if dist > self.clearance:
                            continue
                        hh[i] |= self.hand[a]
                        ah[i] |= self.arm[a]
                        if self.hand[a] and self.clearance - dist >= self.depth[i]:
                            self.depth[i] = self.clearance - dist
                            self.pair[i] = f"{m.geom(int(a)).name} vs {m.geom(int(b)).name}"
        return hh, ah

    def pad_world(self, stance, q, pad):
        d = self.data
        self.place(stance)
        d.qpos[self.qadr] = q
        mujoco.mj_kinematics(self.model, d)
        return d.xpos[self.tcp] + d.xmat[self.tcp].reshape(3, 3) @ pad


class BodyCheck:
    """The whole robot (base, battery, pedestal, torso, neck, both arms at the home pose, grippers open) against the bench, for stances (x, y, heading, pedestal command)."""

    def __init__(self, ctx, open_bench=False):
        self.model = m = copy.copy(ctx.m)
        col = np.array([bool(m.geom_contype[g] or m.geom_conaffinity[g]) for g in range(m.ngeom)])
        root = m.body("base_link").id
        self.robot = np.array([col[g] and m.body_rootid[m.geom_bodyid[g]] == root for g in range(m.ngeom)])
        self.furn = np.array([col[g] and m.body(int(m.geom_bodyid[g])).name == "bench" and not (open_bench and m.geom(g).name.startswith("bench_frame")) for g in range(m.ngeom)])
        for g in range(m.ngeom):
            if not (self.robot[g] or self.furn[g]):
                m.geom_contype[g] = 0
                m.geom_conaffinity[g] = 0
        m.geom_margin[:] = 0.0
        self.data = d = mujoco.MjData(m)
        for sd, home in (("left", TASK_CFG["home_q_left"]), ("right", TASK_CFG["home_q_right"])):
            for a, v in zip(arm_ids(m, sd)["qadr"], home):
                d.qpos[a] = v
            for j in arm_ids(m, sd)["finger_jnt"]:
                d.qpos[m.jnt_qposadr[j]] = STAGING_CFG["finger_open"]
        self.pedestal = [m.joint(jn).qposadr[0] for jn in robot_specs.PEDESTAL_SPECS["joints"]]
        self.base_z = ctx.rg["base_z"]
        self.torso = [g for g in range(m.ngeom) if col[g] and m.body(int(m.geom_bodyid[g])).name == "openarm_body_link0"]

    def place(self, stance):
        d = self.data
        x, y, th, q = stance
        d.qpos[0:7] = [x, y, self.base_z, math.cos(th / 2), 0.0, 0.0, math.sin(th / 2)]
        for a in self.pedestal:
            d.qpos[a] = q
        mujoco.mj_kinematics(self.model, d)

    def hit(self, stance):
        """The name of the robot body that touches the bench, or None."""
        m, d = self.model, self.data
        self.place(stance)
        mujoco.mj_collision(m, d)
        for c in range(d.ncon):
            g1, g2 = d.contact.geom1[c], d.contact.geom2[c]
            if d.contact.dist[c] <= 0:
                for a, b in ((g1, g2), (g2, g1)):
                    if self.furn[b] and self.robot[a]:
                        return m.body(int(m.geom_bodyid[a])).name
        return None

    def torso_front_y(self, stance):
        """The smallest world y of the torso's collision boxes (their bounding boxes), m: the torso's side facing the bench (the bench is at smaller y)."""
        m, d = self.model, self.data
        self.place(stance)
        lows = []
        for g in self.torso:
            c = d.geom_xpos[g] + d.geom_xmat[g].reshape(3, 3) @ m.geom_aabb[g, :3]
            half = np.abs(d.geom_xmat[g].reshape(3, 3)) @ m.geom_aabb[g, 3:]
            lows.append(c[1] - half[1])
        return float(min(lows))


class Runner:
    """One case: the patched search context, the IK check (random starts or with warm starts) and the stance analyses."""

    def __init__(self, name, spec):
        self.name, self.spec = name, spec
        self.warm = spec.get("warm", False)
        self.ctx = ctx = S.Ctx("current", {**TASK_CFG, "bench_open": bool(spec.get("open_bench", False))}, bool(spec.get("cameras", False)))      # the scene's bench is open only in the open case (TASK_CFG's default is open since 2026-10-19)
        C = dict(ctx.C)
        if "level_deg" in spec:
            C["level_deg"] = spec["level_deg"]
        if "margin_deg" in spec:
            C["joint_margin_deg"] = spec["margin_deg"]
        ctx.C = C
        # Ctx.checker keeps one ArmCollisionChecker per pedestal height and each holds a full model copy (about 0.5 GB), so many heights
        # exhaust the 7.4 GB VM (no swap: it freezes). Keep only the 2 most recent; a rebuild takes 0.2 s.
        build = S.Ctx.checker.__get__(ctx)

        def checker(q, keep=2):
            key = round(float(q), 4)
            if key not in ctx._checkers:
                while len(ctx._checkers) >= keep:
                    ctx._checkers.pop(next(iter(ctx._checkers)))
            else:
                ctx._checkers[key] = ctx._checkers.pop(key)     # most recent last
            return build(q)
        ctx.checker = checker
        ctx.lo, ctx.hi = joint_bounds(ctx.m, S.SIDE, C)
        self.margin_deg = C["joint_margin_deg"]
        if "edge_cm" in spec:
            y = ctx.bench_edge_y - spec["edge_cm"] / 100
            ctx.beaker_xy = np.array([ctx.beaker_xy[0], y])
            ctx.hotplate_xy = np.array([ctx.hotplate_xy[0], y])
        self.fracs = tuple(spec.get("fracs", FRACS_ALL))
        H = BEAKER_CFG["height"]
        zg = [ctx.top + f * H for f in self.fracs]
        zs = [ctx.plate_top + 0.002 + f * H for f in self.fracs]
        ctx.points = ([("grasp", f, np.array([*ctx.beaker_xy, z])) for f, z in zip(self.fracs, zg)]
                      + [("setdown", f, np.array([*ctx.hotplate_xy, z])) for f, z in zip(self.fracs, zs)]
                      + [("above", f, np.array([*ctx.hotplate_xy, z + 0.10])) for f, z in zip(self.fracs, zs)])
        ctx.P = np.array([p[2] for p in ctx.points])
        ctx.extreme = [i for i, (_, f, _) in enumerate(ctx.points) if f in (self.fracs[0], self.fracs[-1])]
        self.npts = len(ctx.points)
        self.all_pts = list(range(self.npts))
        self.open = spec.get("open_bench", False)
        self.furn = FurnitureCheck(ctx, self.open, spec.get("hand_clearance", 0.0))
        self.body = BodyCheck(ctx, self.open)
        idx = {(k, f): i for i, (k, f, _) in enumerate(ctx.points)}
        pairs = []
        for kind in ("grasp", "setdown", "above"):
            for a, b in zip(self.fracs[:-1], self.fracs[1:]):
                pairs += [(idx[kind, a], idx[kind, b]), (idx[kind, b], idx[kind, a])]
        for f in self.fracs:
            for k1, k2 in (("above", "setdown"), ("setdown", "grasp"), ("grasp", "setdown")):
                pairs += [(idx[k1, f], idx[k2, f]), (idx[k2, f], idx[k1, f])]
        self.pairs = sorted(set(pairs))

    # ----- limits and IK
    def limits(self, margin_deg=None):
        if margin_deg is None:
            return self.ctx.lo, self.ctx.hi
        rng = self.ctx.m.jnt_range[arm_ids(self.ctx.m, S.SIDE)["jnt"]]
        return rng[:, 0] + math.radians(margin_deg), rng[:, 1] - math.radians(margin_deg)

    def solve_warm(self, stances, pt_idx, margin_deg=None, seeds=24, passes=8):
        """Random starts, then starts from the solutions of neighbouring points: ok0 (random starts only) and ok (all), (n, m, 12) bool, and the joint vectors Q (n, m, 12, 7) of the first solution."""
        ctx = self.ctx
        lo, hi = self.limits(margin_deg)
        T = ctx.to_torso(stances, ctx.P[pt_idx])
        n, m = T.shape[:2]
        ok = np.zeros((n, m, 12), bool)
        Q = np.full((n, m, 12, 7), np.nan)
        for k in ctx.bins:
            flat = T.reshape(-1, 3)
            for a in range(0, len(flat), max(1, 60000 // seeds)):
                sl = slice(a, a + max(1, 60000 // seeds))
                tgt = np.repeat(flat[sl], seeds, axis=0)
                Q0 = ctx.rng.uniform(lo, hi, (len(tgt), 7))
                Qs, good, _ = solve_ik(ctx.chain, Q0, lo, hi, make_constraint(tgt, k, ctx.C), ctx.pad, ctx.C["ik_max_iter"], ctx.C["ik_damping"], ctx.C["ik_max_step"])
                good = good.reshape(-1, seeds)
                first = good.argmax(axis=1)
                Qf = Qs.reshape(-1, seeds, 7)[np.arange(len(good)), first]
                Qf[~good.any(axis=1)] = np.nan
                ok.reshape(-1, 12)[sl, k] = good.any(axis=1)
                Q.reshape(-1, 12, 7)[sl, k] = Qf
        ok0 = ok.copy()
        local = {p: j for j, p in enumerate(pt_idx)}
        pairs = [(local[d_], local[s_]) for d_, s_ in self.pairs if d_ in local and s_ in local]
        for _ in range(passes):
            changed = 0
            for dst, src in pairs:
                for k in ctx.bins:
                    sel = np.nonzero(ok[:, src, k] & ~ok[:, dst, k])[0]
                    if len(sel) == 0:
                        continue
                    Qs, good, _ = solve_ik(ctx.chain, Q[sel, src, k], lo, hi, make_constraint(T[sel, dst], k, ctx.C), ctx.pad, ctx.C["ik_max_iter"], ctx.C["ik_damping"], ctx.C["ik_max_step"])
                    got = sel[good]
                    ok[got, dst, k] = True
                    Q[got, dst, k] = Qs[good]
                    changed += len(got)
            if not changed:
                break
        return ok0, ok, Q

    def body_ok(self, stances):
        """Whether the whole robot at each stance (n, 4) is clear of the bench: (n,) bool."""
        return np.array([self.body.hit(s) is None for s in np.atleast_2d(stances)])

    def plain(self, stances, margin_deg=None):
        """Whether each stance supports every point (no collision checks of the arm; with the open bench the robot must also be clear of it): (n,) bool."""
        stances = np.atleast_2d(stances)
        if self.warm:
            _, ok, _ = self.solve_warm(stances, self.all_pts, margin_deg)
            res = ok.any(axis=2).all(axis=1)
        else:
            res = self.ctx.supports(stances, self.all_pts, 24, cone=False, margin_deg=margin_deg)[0]
        return res & self.body_ok(stances) if self.open else res

    # ----- analyses
    def analyze(self, stances):
        """For stances (n, 4): per stance the point counts of: random starts and robot-self collision-free (the old stage 2), the same with all solutions (warm), and with the hand and fingers
        also clear of the bench and hotplate, and with the whole arm clear of them too. Returns a list of dicts."""
        stances = np.atleast_2d(stances)
        ctx = self.ctx
        ok0, ok, Q = self.solve_warm(stances, self.all_pts) if self.warm else (None, None, None)
        if not self.warm:
            _, ok, Q = self._random_with_q(stances)
            ok0 = ok
        rows = []
        for i, s in enumerate(stances):
            flags = {k: np.zeros(self.npts, bool) for k in ("self0", "self", "hand", "arm")}
            self.detail = {}
            clear_mm = np.full(self.npts, np.nan)
            for p in range(self.npts):
                for key, okm in (("self0", ok0), ("self", ok)):
                    if key == "self0" and not self.warm:
                        continue
                    ks = np.nonzero(okm[i, p])[0]
                    if len(ks) == 0:
                        continue
                    cand = Q[i, p, ks]
                    free = ~ctx.checker(s[3]).check(cand)
                    flags[key][p] = bool(free.any())
                    if key == "self":
                        hh, ah = self.furn.check(s, cand[free]) if free.any() else (np.zeros(0, bool), np.zeros(0, bool))
                        flags["hand"][p] = bool((~hh).any())
                        flags["arm"][p] = bool((~hh & ~ah).any())
                        if len(hh):
                            clear_mm[p] = 1000 * float(self.furn.mindist.max())      # the best candidate's smallest hand distance to the bench or hotplate
                        if free.any() and hh.all():                  # blocked: the least deep hand contact among the candidates
                            j = int(np.argmin(self.furn.depth))
                            self.detail[p] = f"{self.furn.pair[j]} {1000 * self.furn.depth[j]:.1f} mm"
            if not self.warm:
                flags["self0"] = flags["self"]
            flags["body"] = np.full(self.npts, self.body.hit(s) is None)
            flags["detail"] = dict(self.detail)
            flags["clear_mm"] = clear_mm
            rows.append(flags)
        return rows

    def _random_with_q(self, stances):
        ctx = self.ctx
        T = ctx.to_torso(stances, ctx.P).reshape(-1, 3)
        use = np.ones((len(T), 12), bool)
        ok, Qs = ctx.solve(T, use, 24, want_q=True)
        n = len(stances)
        return None, ok.reshape(n, self.npts, 12), Qs.reshape(n, self.npts, 12, 7)

    def grid(self, args):
        return S.grid(self.ctx, args)

    def evaluate(self, s):
        """Margins of one stance: nominal support (robot-self collision-free) and furniture checks, joint margin, tolerances."""
        q_step = robot_specs.PEDESTAL_SPECS["range"][1] / 10
        an = self.analyze(s)[0]
        ladder = sorted({self.margin_deg, 10, 14, 18, 22, 26, 30})
        best_margin = 0
        for mg in ladder:
            if not self.plain(s, mg)[0]:
                break
            best_margin = mg
        dirs8 = [(math.cos(a), math.sin(a)) for a in np.arange(8) * math.pi / 4]
        tol = 0
        for r in TOL_XY_CM:
            cand = np.array([[s[0] + r / 100 * dx, s[1] + r / 100 * dy, s[2], s[3]] for dx, dy in dirs8])
            if not self.plain(cand).all():
                break
            tol = r
        tol_h = 0.0
        for dh in TOL_HEADING:
            cand = np.array([[s[0], s[1], s[2] + sg * math.radians(dh), s[3]] for sg in (-1, 1)])
            if not self.plain(cand).all():
                break
            tol_h = dh
        tol_q = 0.0
        for dq in (0.5, 1.0):
            cand = np.array([[s[0], s[1], s[2], float(np.clip(s[3] + sg * dq * q_step, 0, 0.418))] for sg in (-1, 1)])
            if not self.plain(cand).all():
                break
            tol_q = dq * q_step
        miss = lambda key: [f"{self.ctx.points[p][0]}@{int(round(100 * self.ctx.points[p][1]))}%" + (f" ({an['detail'][p]})" if key == "hand" and p in an["detail"] else "") for p in range(self.npts) if not an[key][p]]
        return dict(x=float(s[0]), y=float(s[1]), heading_deg=math.degrees(s[2]), pedestal_q=float(s[3]), torso_height=0.3048 + float(s[3]), clearance=float(self.ctx.clearance(s[2], s[1])),
                    points=self.npts, points_ok_self=int(an["self"].sum()), points_ok_hand_free=int(an["hand"].sum()), points_ok_arm_free=int(an["arm"].sum()),
                    joint_margin_deg=best_margin, tol_xy_cm=tol, tol_heading_deg=tol_h, tol_pedestal_cm=100 * tol_q,
                    hand_clearance_required_mm=1000 * self.furn.clearance,
                    hand_clearance_mm=[{"point": f"{self.ctx.points[p][0]}@{int(round(100 * self.ctx.points[p][1]))}%", "mm": None if np.isnan(an["clear_mm"][p]) else round(float(an["clear_mm"][p]), 1)} for p in range(self.npts)],
                    hand_blocked_points=miss("hand"), arm_blocked_points=miss("arm"), robot_clear_of_bench=bool(an["body"][0]),
                    torso_front_to_edge_cm=100 * float(self.body.torso_front_y(s) - self.ctx.bench_edge_y), **self.distances(s))

    def distances(self, s):
        """The beaker's distance from the bench edge and from the torso for a stance."""
        ctx = self.ctx
        x, y, th = s[0], s[1], s[2]
        d = ctx.beaker_xy - np.array([x, y])
        c, sn = math.cos(th), math.sin(th)
        fwd, lat = c * d[0] + sn * d[1], -sn * d[0] + c * d[1]
        sh = np.asarray(ctx.shoulder[:2])
        r_beaker = BEAKER_CFG["outer_diameter"] / 2
        return dict(beaker_to_edge_cm=100 * (ctx.bench_edge_y - ctx.beaker_xy[1]), beaker_wall_to_edge_cm=100 * (ctx.bench_edge_y - ctx.beaker_xy[1] - r_beaker),
                    beaker_to_torso_cm=100 * float(np.hypot(*d)), beaker_forward_cm=100 * float(fwd), beaker_lateral_left_cm=100 * float(lat),
                    beaker_to_left_shoulder_cm=100 * float(np.hypot(fwd - sh[0], lat - sh[1])))


def describe(r):
    return (f"x {r['x']:.3f} y {r['y']:.3f} heading {r['heading_deg']:.0f} q {r['pedestal_q']:.3f}: self-free {r['points_ok_self']}/{r['points']}, hand+fingers clear of bench/hotplate "
            f"{r['points_ok_hand_free']}/{r['points']}, whole arm clear {r['points_ok_arm_free']}/{r['points']}; margin {r['joint_margin_deg']} deg, tol xy {r['tol_xy_cm']} cm heading +-{r['tol_heading_deg']:.0f} "
            f"pedestal +-{r['tol_pedestal_cm']:.1f} cm; beaker {r['beaker_to_torso_cm']:.1f} cm from torso ({r['beaker_forward_cm']:.1f} fwd, {r['beaker_lateral_left_cm']:.1f} left), "
            f"{r['beaker_to_edge_cm']:.1f} cm (wall {r['beaker_wall_to_edge_cm']:.1f}) from the bench edge; chassis {100 * r['clearance']:.1f} cm from the edge, torso front {r['torso_front_to_edge_cm']:.1f} cm from it (negative: under the bench), robot clear of bench: {r['robot_clear_of_bench']}" + (f"; hand blocked: {r['hand_blocked_points']}" if r["hand_blocked_points"] else ""))


def sanity(R):
    """The frames are right (the pad centre of a solution is at the target in the world) and the furniture check sees a hand inside the bench."""
    ctx = R.ctx
    s = np.array([0.75, ctx.y_for(math.radians(-100), 0.08), math.radians(-100), 0.0])
    _, ok, Q = R._random_with_q(s[None])
    p = R.all_pts[len(R.all_pts) // 2]
    ks = np.nonzero(ok[0, p])[0]
    if len(ks) == 0:
        log("sanity: no solution at the test stance, frame check skipped")
        return
    w = R.furn.pad_world(s, Q[0, p, ks[0]], ctx.pad)
    err = float(np.linalg.norm(w - ctx.P[p]))
    log(f"sanity: pad centre of a solution is {1000 * err:.1f} mm from its world target (stance {s.round(3).tolist()})")
    assert err < 0.015, "frame mismatch between the IK and the furniture check"
    tgt = np.array([*ctx.beaker_xy, ctx.top - 0.03])
    T = ctx.to_torso(s[None], tgt[None])[0]
    lo, hi = R.limits()
    hits = 0
    got = 0
    for k in ctx.bins:
        Qs, good, _ = solve_ik(ctx.chain, ctx.rng.uniform(lo, hi, (24, 7)), lo, hi, make_constraint(np.repeat(T, 24, axis=0), k, ctx.C), ctx.pad, ctx.C["ik_max_iter"], ctx.C["ik_damping"], ctx.C["ik_max_step"])
        if good.any():
            hh, ah = R.furn.check(s, Qs[good])
            got += len(hh)
            hits += int(hh.sum())
    log(f"sanity: {got} solutions for a pad centre 3 cm inside the bench top, {hits} flagged by the furniture check (must be all of them)")
    assert got == 0 or hits == got


def drive_under(R, args):
    """How far under the open bench the base gets at x 0.75, headings -90 and -100, for each pedestal height: drive in 1 cm at a time from 12 cm outside the edge until the first contact."""
    ctx = R.ctx
    rows = []
    for th_deg in (-90.0, -100.0):
        th = math.radians(th_deg)
        for q in np.linspace(0.0, robot_specs.PEDESTAL_SPECS["range"][1], args.n_q):
            last, part = None, None
            for e in np.arange(0.12, -0.80, -0.01):
                st = np.array([0.75, ctx.y_for(th, e), th, q])
                part = R.body.hit(st)
                if part:
                    break
                last = st
            r = dict(heading_deg=th_deg, pedestal_q=float(q), torso_height=0.3048 + float(q))
            if last is None:
                r.update(chassis_clearance_cm=None, torso_front_to_edge_cm=None, first_contact=part)
            else:
                r.update(chassis_clearance_cm=100 * float(ctx.clearance(th, last[1])), torso_front_to_edge_cm=100 * float(R.body.torso_front_y(last) - ctx.bench_edge_y),
                         base_to_edge_cm=100 * float(last[1] - ctx.bench_edge_y), first_contact=part)
            rows.append(r)
            log(f"drive under: heading {th_deg:.0f} torso height {r['torso_height']:.3f}: deepest clear chassis clearance {r['chassis_clearance_cm']} cm (negative: under), torso front {r['torso_front_to_edge_cm']} cm from the edge, "
                f"next step touches {part}")
    return rows


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--case", required=True, choices=sorted(CASES))
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "d2" / "sens"))
    ap.add_argument("--x-lo", type=float, default=0.45)
    ap.add_argument("--x-hi", type=float, default=1.20)
    ap.add_argument("--x-step", type=float, default=0.03)
    ap.add_argument("--th-lo", type=float, default=-150.0)
    ap.add_argument("--th-hi", type=float, default=-30.0)
    ap.add_argument("--th-step", type=float, default=10.0)
    ap.add_argument("--n-q", type=int, default=8)
    ap.add_argument("--clearances", type=float, nargs="*", default=[0.08, 0.12])
    ap.add_argument("--smoke", action="store_true", help="tiny grid, few evaluations: only to test the script")
    ap.add_argument("--resume", action="store_true")
    args = ap.parse_args()
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    R = Runner(args.case, CASES[args.case])
    ctx = R.ctx
    tag = args.case + ("_smoke" if args.smoke else "")
    log(f"case {args.case} {CASES[args.case]}: {R.npts} points, beaker {ctx.beaker_xy.round(3).tolist()} hotplate {ctx.hotplate_xy.round(3).tolist()}, level {ctx.C['level_deg']} deg, "
        f"joint margin {R.margin_deg} deg, solver {'random + warm starts' if R.warm else 'random starts'}, bench front edge y {ctx.bench_edge_y:.3f}")
    sanity(R)
    if args.smoke:
        args.x_lo, args.x_hi, args.th_lo, args.th_hi, args.n_q = 0.72, 0.78, -110.0, -90.0, 2
    if "clearances" in CASES[args.case]:
        args.clearances = list(CASES[args.case]["clearances"])
    G = R.grid(args)
    if R.open:
        keep = R.body_ok(G)
        log(f"open bench: {int(keep.sum())} of {len(G)} grid stances have the whole robot clear of the bench top and legs")
        G = G[keep]
    stage1_min = CASES[args.case].get("stage1_min", len(ctx.extreme))

    f1 = out / f"{tag}_stage1.json"
    if args.resume and f1.exists():
        s1 = json.loads(f1.read_text())
        counts = np.array(s1["counts"])
        log(f"stage 1 loaded ({len(G)} stances)")
    else:
        log(f"stage 1: {len(G)} stances x {len(ctx.extreme)} extreme points, 12 starts")
        counts = np.zeros(len(G), int)
        B = 800
        for a in range(0, len(G), B):
            _, pt = ctx.supports(G[a:a + B], ctx.extreme, 12)
            counts[a:a + B] = pt.sum(axis=1)
            if (a // B) % 2 == 0:
                log(f"  stage 1: {min(a + B, len(G))}/{len(G)} done, {int((counts[:a + B] == len(ctx.extreme)).sum())} reach all {len(ctx.extreme)}")
        S.save(f1, {"counts": counts.tolist(), "grid": G.tolist()})
    full = int((counts == len(ctx.extreme)).sum())
    cand = G[counts >= stage1_min]
    log(f"stage 1 done: {full} of {len(G)} stances reach all {len(ctx.extreme)} extreme points; candidates for stage 2 (>= {stage1_min}): {len(cand)}")

    f2 = out / f"{tag}_stage2.json"
    if args.resume and f2.exists():
        s2 = json.loads(f2.read_text())
        log("stage 2 loaded")
    else:
        log(f"stage 2: {len(cand)} stances x {R.npts} points x 12 bins")
        rows = []
        for i in range(0, len(cand), 20):
            for s, fl in zip(cand[i:i + 20], R.analyze(cand[i:i + 20])):
                rows.append({"stance": s.tolist(), **{k: bool(fl[k].all()) for k in ("self0", "self", "hand", "arm", "body")}, "hand_points": int(fl["hand"].sum()), "arm_points": int(fl["arm"].sum())})
            if (i // 20) % 5 == 0:
                log(f"  stage 2: {min(i + 20, len(cand))}/{len(cand)} done; random starts {sum(r['self0'] for r in rows)}, all starts {sum(r['self'] for r in rows)}, hand clear {sum(r['hand'] for r in rows)}")
        s2 = {"rows": rows}
        S.save(f2, s2)
    rows = s2["rows"]
    n_self0 = sum(r["self0"] for r in rows)
    n_self = sum(r["self"] for r in rows)
    n_hand = sum(r["hand"] for r in rows)
    n_arm = sum(r["arm"] for r in rows)
    n6 = sum(r["self0"] for r, c in zip(rows, counts[counts >= stage1_min]) if c == len(ctx.extreme))
    log(f"stage 2 done: stances supporting all {R.npts} points, robot-self collision-free: random starts {n_self0} (of those with all 6 extreme points {n6}), with warm starts {n_self}; "
        f"also hand and fingers clear of bench and hotplate: {n_hand}; whole arm clear: {n_arm}")

    hp = np.array([r["hand_points"] for r in rows if r["self"]])
    if len(hp):
        log(f"survivors by number of points with the hand and fingers clear of bench and hotplate (of {R.npts}): " + ", ".join(f"{v}: {int((hp == v).sum())}" for v in sorted(set(hp.tolist()), reverse=True)))
    n_body = sum(r["self"] and r["body"] for r in rows)
    log(f"survivors with the whole robot clear of the bench: {n_body} of {n_self}")
    surv = np.array([r["stance"] for r in rows if r["self"] and (r["body"] or not R.open)])
    results = []
    if len(surv):
        qs = sorted({round(float(r[3]), 6) for r in G})
        q_step = qs[1] - qs[0] if len(qs) > 1 else 1.0
        key = {tuple(np.round(r, 6)) for r in surv}
        proxy = lambda r: sum(tuple(np.round((r[0] + dx, r[1], r[2], r[3] + dq * q_step), 6)) in key for dx, dq in ((args.x_step, 0), (-args.x_step, 0), (0, 1), (0, -1)))
        per_heading = {}
        for th in sorted({round(math.degrees(r[2])) for r in surv}, reverse=True):
            grp = [r for r in surv if round(math.degrees(r[2])) == th]
            best = sorted(grp, key=lambda r: (-proxy(r), r[3], abs(r[0] - 0.75)))[:2 if th in (-90, -100) else 1]
            per_heading[th] = (len(grp), best)
        if args.smoke:
            per_heading = dict(list(per_heading.items())[:1])
        for th, (n, best) in per_heading.items():
            log(f"heading {th}: {n} survivors, evaluating {len(best)}")
            for r in best:
                e = R.evaluate(r)
                results.append(e)
                log("  " + describe(e))
    summary = dict(case=args.case, spec={k: (list(v) if isinstance(v, tuple) else v) for k, v in CASES[args.case].items()}, points=R.npts, grid=len(G), stage1_all_extreme=full, stage1_candidates=len(cand),
                   survivors_random_starts=n_self0, survivors_all_starts=n_self, survivors_hand_clear=n_hand, survivors_arm_clear=n_arm, survivors_robot_clear_of_bench=n_body, hand_points_histogram={int(v): int((hp == v).sum()) for v in sorted(set(hp.tolist()))} if len(hp) else {}, evaluated=results)
    if R.open:
        summary["drive_under"] = drive_under(R, args)
    if results:
        results.sort(key=lambda r: (-r["tol_xy_cm"], -r["tol_heading_deg"], -r["joint_margin_deg"]))
        summary["best"] = results[0]
        for th in (-90, -100):
            at = [r for r in results if round(r["heading_deg"]) == th]
            summary[f"best_at_{-th}"] = max(at, key=lambda r: (r["tol_xy_cm"], r["tol_heading_deg"])) if at else None
        summary["best_heading_deg"] = results[0]["heading_deg"]
    S.save(out / f"{tag}_summary.json", summary)
    log(f"RESULT {args.case}: {n_self if R.warm else n_self0} stances reach all {R.npts} points; hand+fingers clear: {n_hand}; best: " + (describe(results[0]) if results else "none"))


if __name__ == "__main__":
    main()
